# Kakerlakken ligger i romgrafikken/objekter; ingen egen bekreftet kostyme-ID i dette grunnlaget.
rows=[x for x in rows if x[0]!='kakerlakk']
f=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',17)
records=[]
for slug,name,ids,kind,identity,evidence,detail in rows:
 ims=[]
 for cid in ids:
  c=meta[str(cid)]; seen=set()
  for cel in sorted(c['cels'],key=lambda x:x['w']*x['h'],reverse=True):
   q=src/'costumes'/f"costume{cid:03d}_{cel['cel']:03d}.png"
   digest=hashlib.sha256(q.read_bytes()).hexdigest()
   if digest in seen:continue
   seen.add(digest);ims.append((q,cel,c['room'],digest))
   if len(seen)>=3:break
 out=Image.new('RGB',(1200,60+((len(ims)+3)//4)*270),(180,180,180));d=ImageDraw.Draw(out)
 d.text((12,8),name+' | ORIGINAL, ikke HD | palett fra lagringsrom',font=f,fill='black')
 for k,(q,cel,r,digest) in enumerate(ims):
  x=k%4*300;y=45+k//4*270
  d.text((x+5,y),q.stem,font=f,fill='black');d.text((x+5,y+22),f'Rom {r}, lag {cel["lag"]}',font=f,fill='black')
  im=Image.open(q).convert('RGBA');s=min(280/im.width,210/im.height);im=im.resize((max(1,round(im.width*s)),max(1,round(im.height*s))),Image.Resampling.NEAREST);out.paste(im,(x+(300-im.width)//2,y+50),im)
 ref=base/'referanser'/f'{slug}.png'
 if slug!='bruno':out.save(ref)
 prompt='Use case: stylized-concept. Asset: preliminary HD identity concept, not a production spritesheet. Use ONLY the supplied original sprite contact sheet as identity authority. The subject is '+name+' from Sam & Max Hit the Road (1993). '+detail+' Preserve the original 1993 hand-inked cartoon anatomy, proportions, irregular black outlines and flat local colors. Smooth 2D ink and restrained cel shading, neutral pale gray background, no dramatic lighting, no 3D, no realistic fur, no redesign. Show ONE faithful main drawing in an actually evidenced source pose with ONE enlarged head detail from that same drawing where useful. Do not invent alternate directions, turnarounds, action poses, props, limbs, clothing, teeth or missing anatomy. Contact-sheet fragments are parts of the subject, not separate people. If only a head is shown, deliver a head study and preserve the head-only scope. Keep any other characters out except explicitly paired subjects. No decorative text or source IDs; small title exactly: "'+name+'".'
 (base/'prompter'/f'{slug}.txt').write_text(prompt+'\n')
 records.append(dict(id=slug,name=name,kind=kind,costumes=ids,identity=identity,evidence=evidence.split(';'),reference=f'referanser/{slug}.png',prompt=f'prompter/{slug}.txt',concept=f'bilder/{slug}.png',status='konsept planlagt',sources=[dict(file=str(q.relative_to(root)),sha256=digest,cel=cel,room=r) for q,cel,r,digest in ims]))
(base/'figurer.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n')
print('Kildeark og prompter for',len(records),'motiver skrevet')
